function sweepEntry(brick, px, py, dx, dy, r) {
  // Expanded AABB: the ball of radius r becomes a point against a box grown by r.
  const minX = brick.x - r, maxX = brick.x + brick.w + r;
  const minY = brick.y - r, maxY = brick.y + brick.h + r;

  let tEnterX, tExitX;
  if (dx === 0) {
    if (px <= minX || px >= maxX) return null; // never crosses
    tEnterX = -Infinity; tExitX = Infinity;
  } else {
    const t1 = (minX - px) / dx;
    const t2 = (maxX - px) / dx;
    tEnterX = Math.min(t1, t2);
    tExitX = Math.max(t1, t2);
  }
  let tEnterY, tExitY;
  if (dy === 0) {
    if (py <= minY || py >= maxY) return null;
    tEnterY = -Infinity; tExitY = Infinity;
  } else {
    const t1 = (minY - py) / dy;
    const t2 = (maxY - py) / dy;
    tEnterY = Math.min(t1, t2);
    tExitY = Math.max(t1, t2);
  }

  const tEnter = Math.max(tEnterX, tEnterY);
  const tExit = Math.min(tExitX, tExitY);
  if (tEnter > tExit) return null;         // misses the slab
  if (tExit < 0) return null;              // box is behind the segment start... 
  if (tEnter > 1) return null;             // box beyond the segment end
  return { t: Math.max(tEnter, 0), face: ... };
}
```

