export function brickHit(ball, bricks, prevX = ball.prevX ?? ball.x, prevY = ball.prevY ?? ball.y) {
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  // --- find the first live brick hit along the swept segment ---
  let best = null; // { brick, t, face }
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweepEntry(brick, prevX, prevY, dx, dy, ball.r);
    if (hit && (best === null || hit.t < best.t)) best = { brick, ...hit };
  }
  if (!best) return [];

  const { brick, t, face } = best;
  const ex = prevX + dx * t; // circle centre at first contact
  const ey = prevY + dy * t;
  const EPS = 0.001;

  // --- bounce exactly once, on the face that was hit ---
  if (face === 'x') {
    ball.vx = -ball.vx;
    ball.x = dx >= 0 ? brick.x - ball.r - EPS : brick.x + brick.w + ball.r + EPS;
    ball.y = ey;
  } else if (face === 'y') {
    ball.vy = -ball.vy;
    ball.x = ex;
    ball.y = dy >= 0 ? brick.y - ball.r - EPS : brick.y + brick.h + ball.r + EPS;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = dx >= 0 ? brick.x - ball.r - EPS : brick.x + brick.w + ball.r + EPS;
    ball.y = dy >= 0 ? brick.y - ball.r - EPS : brick.y + brick.h + ball.r + EPS;
  }

  // --- destroy the hit brick plus every brick the ball touches (seams) ---
  const destroyed = [];
  for (const b of bricks) {
    if (!b.alive) continue;
    if (b === brick || collides(ball, b)) {
      b.alive = false;
      destroyed.push(b);
    }
  }
  return destroyed;
}
```

