edits.newText:
// --- Collision (tested primitives) -----------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — `brickHit()` below answers that.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Sweeps the segment from (px, py) to (px + dx, py + dy) against one brick
// grown by the ball radius (the circle becomes a point). Returns the entry
// time `t` in [0, 1], the face hit first (`x`, `y` or `corner`) and the side
// to push the ball out on — or null if the segment never crosses the brick.
function sweepEntry(brick, px, py, dx, dy, r) {
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;

  let tEnterX, tExitX, sideX;
  if (dx === 0) {
    if (px <= minX || px >= maxX) return null; // never crosses the X slab
    tEnterX = -Infinity;
    tExitX = Infinity;
    sideX = px - minX < maxX - px ? 'left' : 'right';
  } else {
    const t1 = (minX - px) / dx;
    const t2 = (maxX - px) / dx;
    tEnterX = Math.min(t1, t2);
    tExitX = Math.max(t1, t2);
    sideX = dx > 0 ? 'left' : 'right';
  }

  let tEnterY, tExitY, sideY;
  if (dy === 0) {
    if (py <= minY || py >= maxY) return null; // never crosses the Y slab
    tEnterY = -Infinity;
    tExitY = Infinity;
    sideY = py - minY < maxY - py ? 'top' : 'bottom';
  } else {
    const t1 = (minY - py) / dy;
    const t2 = (maxY - py) / dy;
    tEnterY = Math.min(t1, t2);
    tExitY = Math.max(t1, t2);
    sideY = dy > 0 ? 'top' : 'bottom';
  }

  const tEnter = Math.max(tEnterX, tEnterY);
  const tExit = Math.min(tExitX, tExitY);
  if (tEnter > tExit || tExit <= 0 || tEnter > 1) return null;

  let face;
  if (tEnterX === -Infinity && tEnterY === -Infinity) {
    // Ball did not move this step: fall back to the penetration rule.
    const ox = Math.min(px - minX, maxX - px);
    const oy = Math.min(py - minY, maxY - py);
    face = Math.abs(ox - oy) < 1e-6 ? 'corner' : ox < oy ? 'x' : 'y';
  } else if (Math.abs(tEnterX - tEnterY) < 1e-6) {
    face = 'corner'; // equal penetrations: diagonal hit
  } else {
    face = tEnterX > tEnterY ? 'x' : 'y'; // the axis that entered last is the face
  }

  return { t: Math.max(tEnter, 0), face, sideX, sideY };
}

// Resolves the ball against the live bricks for one time step.
//
// Every case from issue #1 is handled here:
//   * per face   — the axis that entered last is the face that was hit: flip
//                  `vy` on a top/bottom hit, `vx` on a side hit; the other
//                  component is left exactly as it was;
//   * corner     — equal penetrations mean a diagonal hit: flip both;
//   * push out   — the ball is repositioned just outside the brick, otherwise
//                  it keeps overlapping and re-flips forever (sticky bounce);
//   * neighbours — the 8 px grid gap is smaller than the 14 px ball, so a seam
//                  overlaps two bricks in the SAME pass: the bounce is applied
//                  exactly once and every touched brick is destroyed;
//   * tunnelling — the segment from the ball's previous position to its
//                  current one is swept, so a fast ball (level 6 + a stuttered
//                  50 ms frame) cannot jump over a brick between two frames.
//
// Returns the bricks destroyed this pass (score/combo is the caller's job).
export function brickHit(ball, bricks, prevX = ball.prevX ?? ball.x, prevY = ball.prevY ?? ball.y) {
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  // Sweep every live brick, keep the earliest hit: that is the face to resolve.
  let best = null;
  const crossed = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = sweepEntry(brick, prevX, prevY, dx, dy, ball.r);
    if (!hit) continue;
    crossed.push({ brick, ...hit });
    if (!best || hit.t < best.t) best = { brick, ...hit };
  }
  if (!best) return [];

  const { brick, t, face, sideX, sideY } = best;
  const ex = prevX + dx * t; // ball centre at first contact
  const ey = prevY + dy * t;
  const EPS = 0.001;

  // Bounce exactly once, on the face that was hit first.
  if (face === 'x') {
    if (sideX === 'left' ? ball.vx > 0 : ball.vx < 0) ball.vx = -ball.vx;
    ball.x = sideX === 'left' ? brick.x - ball.r - EPS : brick.x + brick.w + ball.r + EPS;
    ball.y = ey;
  } else if (face === 'y') {
    if (sideY === 'top' ? ball.vy > 0 : ball.vy < 0) ball.vy = -ball.vy;
    ball.x = ex;
    ball.y = sideY === 'top' ? brick.y - ball.r - EPS : brick.y + brick.h + ball.r + EPS;
  } else {
    if (sideX === 'left' ? ball.vx > 0 : ball.vx < 0) ball.vx = -ball.vx;
    if (sideY === 'top' ? ball.vy > 0 : ball.vy < 0) ball.vy = -ball.vy;
    ball.x = sideX === 'left' ? brick.x - ball.r - EPS : brick.x + brick.w + ball.r + EPS;
    ball.y = sideY === 'top' ? brick.y - ball.r - EPS : brick.y + brick.h + ball.r + EPS;
  }

  // Destroy the brick that was hit plus every brick the ball still touches:
  // at a seam the sweep crosses two bricks at the same instant — one bounce,
  // both destroyed.
  const destroyed = [];
  for (const hit of crossed) {
    const b = hit.brick;
    if (!b.alive) continue;
    if (hit.t <= t + 1e-6 || collides(ball, b)) {
      b.alive = false;
      destroyed.push(b);
    }
  }
  return destroyed;
}

