export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball was: brickHit() sweeps this segment to catch fast
  // balls that would otherwise tunnel through a brick in a single frame.
  ball.prevX = ball.x;
  ball.prevY = ball.y;

  ball.x += ball.vx * dt;

