edits.newText:
// --- Issue #1: brick bounce -------------------------------------------------

test('brickHit: head-on top hit flips vy, leaves vx, pushes the ball out', () => {
  const brick = { x: 80, y: 100, w: 40, h: 20, alive: true };
  const ball = { x: 100, y: 140, r: 7, vx: 0, vy: 400 };
  const destroyed = brickHit(ball, [brick], 100, 60);
  assert.equal(destroyed.length, 1);
  assert.equal(destroyed[0], brick);
  assert.equal(brick.alive, false);
  assert.equal(Math.sign(ball.vy), UP);
  assert.equal(ball.vx, 0, 'horizontal component untouched');
  assert.ok(ball.y + ball.r <= brick.y, 'ball pushed back out above the brick');
});

test('brickHit: side hit flips vx, leaves vy untouched', () => {
  const brick = { x: 200, y: 100, w: 40, h: 20, alive: true };
  const ball = { x: 250, y: 110, r: 7, vx: 400, vy: -30 };
  const destroyed = brickHit(ball, [brick], 150, 110);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vx, -400);
  assert.equal(ball.vy, -30, 'vertical component left exactly as it was');
  assert.ok(ball.x + ball.r <= brick.x, 'ball pushed back out to the left');
});

test('brickHit: hitting the right face flips vx the other way', () => {
  const brick = { x: 200, y: 100, w: 40, h: 20, alive: true };
  const ball = { x: 230, y: 110, r: 7, vx: -400, vy: 0 };
  const destroyed = brickHit(ball, [brick], 274, 110);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vx, 400);
  assert.equal(ball.vy, 0);
  assert.ok(ball.x - ball.r >= brick.x + brick.w, 'ball pushed back out to the right');
});

test('brickHit: equal penetrations on a corner flip both components', () => {
  const brick = { x: 200, y: 100, w: 40, h: 20, alive: true };
  // Perfect diagonal: the ball reaches the top-left corner of the brick.
  const ball = { x: 193, y: 93, r: 7, vx: 400, vy: 400 };
  const destroyed = brickHit(ball, [brick], 133, 33);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vx, -400);
  assert.equal(ball.vy, -400);
  assert.ok(ball.x + ball.r <= brick.x);
  assert.ok(ball.y + ball.r <= brick.y);
});

test('brickHit: a seam between two bricks destroys both with a single bounce', () => {
  const a = { x: 100, y: 100, w: 72, h: 20, alive: true };
  const b = { x: 180, y: 100, w: 72, h: 20, alive: true }; // 8 px gap, ball is 14 px
  const ball = { x: 174, y: 140, r: 7, vx: 0, vy: 400 }; // straddles both bricks
  const destroyed = brickHit(ball, [a, b], 174, 60);
  assert.equal(destroyed.length, 2);
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.equal(ball.vy, -400, 'vy flipped exactly once, not twice');
  assert.equal(ball.vx, 0);
});

test('brickHit: a fast ball cannot tunnel through a brick in one step', () => {
  const brick = { x: 80, y: 100, w: 40, h: 20, alive: true };
  // The ball jumps from y = 60 to y = 200: it never ends up overlapping the
  // brick, only the swept segment sees the crossing.
  const ball = { x: 100, y: 200, r: 7, vx: 0, vy: 1400 };
  const destroyed = brickHit(ball, [brick], 100, 60);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vy, -1400);
  assert.ok(ball.y + ball.r <= brick.y, 'ball pushed back out above the brick');
});

test('brickHit: ball resting against a face and moving away does not re-flip', () => {
  const brick = { x: 80, y: 100, w: 40, h: 20, alive: true };
  // The ball sits exactly against the top face and moves UP (away).
  const ball = { x: 100, y: 80, r: 7, vx: 0, vy: -400 };
  const destroyed = brickHit(ball, [brick], 100, 93);
  assert.equal(destroyed.length, 0);
  assert.equal(ball.vy, -400, 'no sticky re-bounce');
  assert.equal(brick.alive, true);
});

test('brickHit: a clear miss destroys nothing and changes nothing', () => {
  const brick = { x: 80, y: 100, w: 40, h: 20, alive: true };
  const ball = { x: 300, y: 300, r: 7, vx: 100, vy: 200 };
  const destroyed = brickHit(ball, [brick], 295, 295);
  assert.equal(destroyed.length, 0);
  assert.equal(brick.alive, true);
  assert.equal(ball.vx, 100);
  assert.equal(ball.vy, 200);
});

test('step + brickHit: one full frame bounces the ball off a brick', () => {
  const state = createState(1);
  state.bricks = [{ x: 200, y: 100, w: 72, h: 20, row: 0, alive: true, points: 50 }];
  state.ball = { x: 236, y: 150, r: 7, vx: 0, vy: -400 };
  step(state, 0.06); // records prev, moves the ball up past the brick's face
  const destroyed = brickHit(state.ball, state.bricks);
  assert.equal(destroyed.length, 1);
  assert.equal(Math.sign(state.ball.vy), DOWN, 'ball rebounds downward');
  assert.ok(state.ball.y + state.ball.r >= 120, 'ball pushed below the brick');
});

test('brickHit on the real grid: the ball bounces off the first brick it meets', () => {
  const bricks = makeBricks(1);
  const target = bricks.find((b) => b.row === 4 && b.col === 3);
  const cx = target.x + target.w / 2;
  const ball = { x: cx, y: 185, r: 7, vx: 0, vy: -700 };
  const destroyed = brickHit(ball, bricks, cx, 210);
  assert.equal(destroyed.length, 1);
  assert.equal(destroyed[0], target);
  assert.equal(Math.sign(ball.vy), DOWN, 'rebounds downward instead of plowing through');
});

test('frame: scoring and bouncing a destroyed brick happen together', () => {
  const state = createState(1);
  state.bricks = [{ x: 200, y: 100, w: 72, h: 20, row: 0, alive: true, points: 50 }];
